INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q16543736', 'Spanish conquest of Tripoli', 'The Conquest of Tripoli was a maritime campaign led by Pedro Navarro which captured the city of Tripoli in North Africa in the name of the Crown of Aragon in 1510.', 1510, 7, 22, 1510, 7, 25, 'day', '22 July 1510 – 25 July 1510', 41, 'https://en.wikipedia.org/wiki/Spanish_conquest_of_Tripoli'),
  ('Q2860095', 'Siege of Tripoli', 'The siege of Tripoli was a successful Ottoman siege of the North African city of Tripoli, then held by the Knights Hospitaller, in August 1551. The attack, which was led by Sinan Pasha and Dragut, appears to have been launched in retaliation for the capture of Mahdia by the Spanish and Hospitallers the previous year.', 1551, 8, 9, 1551, 8, 15, 'day', '9 August 1551 – 15 August 1551', 51, 'https://en.wikipedia.org/wiki/Siege_of_Tripoli_(1551)'),
  ('Q6135223', 'Second Battle of Tripoli Harbor', 'The Second Battle of Tripoli Harbor was a naval action that occurred during the American naval blockade, which took place in Tripoli Harbor between August and September 1804. The battle was part of the First Barbary War between forces of the United States and the forces of the Eyalet of Tripolitania.', 1804, 8, 3, 1804, 9, 10, 'day', '3 August 1804 – 10 September 1804', 39, 'https://en.wikipedia.org/wiki/Second_Battle_of_Tripoli_Harbor'),
  ('Q2888407', 'Battle of Derna', 'The Battle of Derna at Derna, Cyrenaica, was a military engagement in April–May 1805 of a mercenary army recruited and led by United States Marines under the command of U.S. Army Lieutenant William Eaton, diplomatic Consul to Tripoli, and U.S. Marine Corps First Lieutenant Presley O''Bannon. The battle involved a 521-mile (839-km) march through the Libyan Desert from Alexandria, Egypt, to the eastern port city of Derna, which was defended by a much larger force.', 1805, 4, 27, 1805, 6, 12, 'day', '27 April 1805 – 12 June 1805', 50, 'https://en.wikipedia.org/wiki/Battle_of_Derna_(1805)'),
  ('Q2624980', 'Battle of Tobruk', 'The Battle of Tobruk (1911) or Nadura Hill Battle occurred on 22 December 1911 during the Italo-Turkish War for the control of the Nadura Hill near Tobruk (a city the Italians had occupied in October). The battle was a small engagement primarily known for the involvement and leadership of future Turkish president Mustafa Kemal Atatürk.', 1911, 12, 22, NULL, NULL, NULL, 'day', '22 December 1911', 45, 'https://en.wikipedia.org/wiki/Battle_of_Tobruk_(1911)'),
  ('Q16487664', 'Battle of Ain Zara', 'The Battle of Ain Zara was fought in December 1911 during the Italo-Turkish War between the Kingdom of Italy and Ottoman Empire forces for the control of the oasis of Ain Zara, near Tripoli in modern Libya, where the Ottomans had established a fortified base.', 1911, 12, 4, NULL, NULL, NULL, 'day', '4 December 1911', 39, 'https://en.wikipedia.org/wiki/Battle_of_Ain_Zara'),
  ('Q16592086', 'Battle of Tripoli', 'The Battle of Tripoli was fought in October 1911, during the initial stages of the Italo-Turkish War, and saw the capture of Tripoli, capital city of Tripolitania (and present-day Libya), by Italian landing forces. It marked the beginning of the land campaign in Libya of the Italo-Turkish War as well as the beginning of the Italian colonization of Libya.', 1911, 10, 10, NULL, NULL, NULL, 'day', '10 October 1911', 41, 'https://en.wikipedia.org/wiki/Battle_of_Tripoli_(1911)'),
  ('Q124005579', 'Libyan genocide', 'The Libyan genocide, also known in Libya as Shar (Arabic: شر, lit. ''Evil''), was the genocide of Libyan Arabs and the systematic destruction of Libyan culture during and after the Second Italo-Senussi War between 1929 and 1934. During this period, between 20,000 and 100,000 Libyans were killed by Italian colonial authorities under Benito Mussolini.', 1929, NULL, NULL, 1934, NULL, NULL, 'year', '1929–1934', 37, 'https://en.wikipedia.org/wiki/Libyan_genocide_(1929%E2%80%931934)'),
  ('Q18216807', 'Siege of Giarabub', 'The siege of Giarabub (now Jaghbub) in Libya, was an engagement between Commonwealth and Italian forces, during the Western Desert Campaign of the Second World War. In the aftermath of Operazione E, the invasion of Egypt by the Italian 10th Army (9–16 September 1940), Operation Compass (9–16 December) by the Western Desert Force (WDF), the Battle of Sidi Barrani and the pursuit of the 10th Army into Cyrenaica (16 December 1940 – 9 February 1941) the fortified Italian position at the Al Jaghbub Oasis was besieged by parts of the 6th Australian Division.', 1940, 12, 25, 1941, 3, 21, 'day', '25 December 1940 – 21 March 1941', 41, 'https://en.wikipedia.org/wiki/Siege_of_Giarabub'),
  ('Q611089', 'Siege of Tobruk', 'The siege of Tobruk took place between 10 April and 27 November 1941, during the Western Desert campaign (1940–1943) of the Second World War. An Allied force, consisting mostly of the 9th Australian Division, commanded by Lieutenant-General Leslie Morshead, was besieged in the North African port of Tobruk by German and Italian forces.', 1941, 4, 10, 1941, 11, 27, 'day', '10 April 1941 – 27 November 1941', 67, 'https://en.wikipedia.org/wiki/Siege_of_Tobruk'),
  ('Q708223', 'Operation Sonnenblume', 'Operation Sonnenblume (Unternehmen Sonnenblume, "Operation Sunflower") was the name given to the dispatch of German and Italian troops to North Africa in February 1941, during the Second World War. The Italian 10th Army (10ª Armata) had been destroyed by the British, Commonwealth, Empire and Allied Western Desert Force attacks during Operation Compass (9 December 1940 – 9 February 1941).', 1941, 2, 6, 1941, 5, 25, 'day', '6 February 1941 – 25 May 1941', 62, 'https://en.wikipedia.org/wiki/Operation_Sonnenblume'),
  ('Q2426368', 'Battle of Bardia', 'The Battle of Bardia was fought between 3 and 5 January 1941, as part of Operation Compass, the first British military operation of the Western Desert campaign of the Second World War. It was the first battle of the war in which an Australian Army formation took part, the first to be commanded by an Australian general and the first to be planned by an Australian staff.', 1941, 1, 3, 1941, 1, 5, 'day', '3 January 1941 – 5 January 1941', 52, 'https://en.wikipedia.org/wiki/Battle_of_Bardia'),
  ('Q2616448', 'Battle of Kufra', 'The Capture of Kufra (French: Prise de Koufra, Italian: Cufra) was part of the Allied Western Desert Campaign during the Second World War. Kufra is a group of oases in the Kufra District of south-eastern Cyrenaica in the Libyan Desert.', 1941, 1, 31, 1941, 3, 1, 'day', '31 January 1941 – 1 March 1941', 45, 'https://en.wikipedia.org/wiki/Capture_of_Kufra'),
  ('Q76643875', 'British capture of Tobruk', 'The British capture of Tobruk was a battle fought between 21 and 22 January 1941, as part of Operation Compass, the first offensive of the Western Desert Force (WDF) in the Western Desert Campaign of the Second World War. After defeating the Italians in the Battle of Bardia (3–5 January 1941), the 6th Australian Division and the 7th Armoured Division pressed on and made contact with the Italian garrison in Tobruk on 6 January.', 1941, 1, 21, 1941, 1, 22, 'day', '21 January 1941 – 22 January 1941', 39, 'https://en.wikipedia.org/wiki/British_capture_of_Tobruk'),
  ('Q327035', 'Battle of Gazala', 'The Battle of Gazala, also the Gazala Offensive (Italian: Battaglia di Ain el-Gazala; German: Schlacht von Gazala), was fought near the village of Gazala during the Western Desert Campaign of the Second World War, west of the port of Tobruk in Libya, from 26 May to 21 June 1942. Axis troops consisting of German (Panzerarmee Afrika; Generaloberst Erwin Rommel) and Italian units fought the British Eighth Army (General Sir Claude Auchinleck, also Commander-in-Chief Middle East) composed mainly of British Commonwealth, Indian and Free French troops.', 1942, 5, 26, 1942, 6, 21, 'day', '26 May 1942 – 21 June 1942', 69, 'https://en.wikipedia.org/wiki/Battle_of_Gazala'),
  ('Q836128', 'Battle of Bir Hakeim', 'The Battle of Bir Hakeim (Arabic pronunciation: [biʔr ħaˈkiːm] ) took place at Bir Hakeim, an oasis in the Libyan desert southwest of Tobruk, during the Battle of Gazala (26 May – 21 June 1942). The 1st Free French Brigade (Général de brigade Marie-Pierre Kœnig) defended the position from 26 May to 11 June against Axis forces of the Panzerarmee Afrika (Generaloberst Erwin Rommel) that captured Tobruk ten days later.', 1942, 5, 26, 1942, 6, 11, 'day', '26 May 1942 – 11 June 1942', 65, 'https://en.wikipedia.org/wiki/Battle_of_Bir_Hakeim'),
  ('Q2371769', 'Battle of El Agheila', 'The Battle of El Agheila was a brief engagement of the Western Desert Campaign of the Second World War. It took place in December 1942 between Allied forces of the Eighth Army (General Bernard Montgomery) and the Axis forces of the German-Italian Panzer Army (Generalfeldmarschall Erwin Rommel), during the long Axis withdrawal from El Alamein to Tunis.', 1942, 12, 11, 1942, 12, 18, 'day', '11 December 1942 – 18 December 1942', 51, 'https://en.wikipedia.org/wiki/Battle_of_El_Agheila'),
  ('Q85744444', 'Axis capture of Tobruk', 'The Axis capture of Tobruk, also known as the Fall of Tobruk and the Second Battle of Tobruk (17–21 June 1942) was part of the Western Desert campaign in Libya during the Second World War. The battle was fought by the Panzerarmee Afrika (Armata Corazzata Africa in Italian), a German–Italian military force in North Africa which included the Afrika Korps (Generalleutnant Erwin Rommel), against the British Eighth Army (General Neil Ritchie) which comprised contingents from Britain, India, South Africa and other Allied nations.', 1942, 6, 21, NULL, NULL, NULL, 'day', '21 June 1942', 37, 'https://en.wikipedia.org/wiki/Axis_capture_of_Tobruk'),
  ('Q2604253', 'Gulf of Sidra incident', 'In the first Gulf of Sidra incident, 19 August 1981, two Libyan Sukhoi Su-22M3 Fitter-G fired upon two U.S. Grumman F-14A Tomcats and were subsequently shot down off the Libyan coast. Libya had claimed that the entire Gulf was their territory, at 32° 30′ N, with an exclusive 62-nautical-mile (115 km; 71 mi) fishing zone, which Libyan leader Muammar Gaddafi asserted as "The Line of Death" in 1973.', 1981, 8, 19, NULL, NULL, NULL, 'day', '19 August 1981', 53, 'https://en.wikipedia.org/wiki/Gulf_of_Sidra_incident_(1981)'),
  ('Q4271998', 'Battle of Maaten al-Sarra', 'The Battle of Maaten al-Sarra was fought between Chad and Libya on September 5, 1987, during the Toyota War. The battle took the form of a surprise Chadian raid against the Libyan Maaten al-Sarra Air Base, meant to remove the threat of Libyan airpower, that had already thwarted the Chadian attack on the Aouzou Strip in August.', 1987, 9, 5, NULL, NULL, NULL, 'day', '5 September 1987', 43, 'https://en.wikipedia.org/wiki/Battle_of_Maaten_al-Sarra'),
  ('Q626003', 'Korean Air Flight 803', 'Korean Air Flight 803 was a scheduled international passenger flight operated by Korean Air from Seoul to Tripoli via Bangkok and Jeddah. On 27 July 1989, the McDonnell Douglas DC-10 operating the flight crashed while attempting to land in Tripoli, Libya.', 1989, 7, 27, NULL, NULL, NULL, 'day', '27 July 1989', 48, 'https://en.wikipedia.org/wiki/Korean_Air_Flight_803'),
  ('Q4117937', 'Libyan Arab Airlines Flight 1103', 'Libyan Arab Airlines Flight 1103 was a Boeing 727-2L5 with 9 crew members and 150 passengers on board that collided with a LARAF Mikoyan-Gurevich MiG-23UB on 22 December 1992. All 159 people on board Flight 1103 were killed, while the pilot and instructor of the MiG-23 ejected and survived.', 1992, 12, 22, NULL, NULL, NULL, 'day', '22 December 1992', 51, 'https://en.wikipedia.org/wiki/Libyan_Arab_Airlines_Flight_1103'),
  ('Q9291337', 'Abu Salim Prison massacre', 'Abu Salim prison (Arabic: سجن أبو سليم, romanized: Sijn Abū Salīm) is a maximum security prison in Tripoli, Libya. The prison was notorious during the rule of Muammar Gaddafi for alleged mistreatment and human rights abuses, including a massacre in 1996 in which Human Rights Watch estimated that 1,270 prisoners were killed.', 1996, 6, 28, 1996, 6, 29, 'day', '28 June 1996 – 29 June 1996', 41, 'https://en.wikipedia.org/wiki/Abu_Salim_Prison_massacre'),
  ('Q387892', 'Afriqiyah Airways Flight 771', 'Afriqiyah Airways Flight 771 was a scheduled international Afriqiyah Airways passenger flight from Johannesburg, South Africa to Tripoli, Libya. On 12 May 2010 at about 06:01 (04:01 UTC) while on approach to Tripoli International Airport, the aircraft operating the flight, an Airbus A330, crashed about 1,200 metres (3,900 ft; 1,300 yd) short of the runway.', 2010, 5, 12, NULL, NULL, NULL, 'day', '12 May 2010', 63, 'https://en.wikipedia.org/wiki/Afriqiyah_Airways_Flight_771'),
  ('Q81545', 'Libyan Civil War', 'The Libyan Civil War, also known as the First Libyan Civil War and Libyan Revolution, was an armed conflict fought in 2011 in the North African country of Libya between forces loyal to Colonel Muammar Gaddafi and rebel groups attempting to oust his government. The war was ignited by protests in Benghazi beginning on 15 February 2011 inspired by the Arab Spring, which led to clashes with security forces and armed protesters.', 2011, 2, 15, 2011, 10, 23, 'day', '15 February 2011 – 23 October 2011', 85, 'https://en.wikipedia.org/wiki/Libyan_civil_war_(2011)'),
  ('Q210714', '2011 military intervention in Libya', 'On 19 March 2011, a NATO-led coalition began a military intervention into the ongoing Libyan Civil War to implement United Nations Security Council Resolution 1973 (UNSCR 1973). The UN Security Council passed the resolution with ten votes in favour and five abstentions, with the stated intent to have "an immediate ceasefire in Libya, including an end to the current attacks against civilians, which it said might constitute ''crimes against humanity'' ...', 2011, 10, 31, 2011, 10, 31, 'day', '31 October 2011', 72, 'https://en.wikipedia.org/wiki/2011_military_intervention_in_Libya'),
  ('Q277176', 'Nafusa Mountains campaign', 'The Nafusa Mountains campaign was a series of battles in the Libyan Civil War, fought between loyalist pro-Gaddafi forces and rebel anti-Gaddafi forces in the Nafusa Mountains and, at a later period, in the surrounding plains of western Libya. The mountain range is of strategic importance due to its close proximity to Tripoli, the Libyan capital.', 2011, 8, 18, NULL, NULL, NULL, 'day', '18 August 2011', 41, 'https://en.wikipedia.org/wiki/Nafusa_Mountains_campaign'),
  ('Q371620', 'First Battle of Benghazi', 'The First Battle of Benghazi was fought between army units and militiamen loyal to Libyan leader Muammar Gaddafi and anti-Gaddafi forces in February 2011 during the Libyan Civil War. The battle mainly took place in Benghazi, the second-largest city in Libya, with related clashes occurring in the nearby Cyrenaican cities of Bayda and Derna.', 2011, 2, 15, 2011, 2, 20, 'day', '15 February 2011 – 20 February 2011', 45, 'https://en.wikipedia.org/wiki/First_Battle_of_Benghazi'),
  ('Q506595', 'Battle of Ajdabiya', 'The Battle of Ajdabiya was an armed battle in and near the city of Ajdabiya that took place as part of the Libyan Civil War. It was fought between anti-government rebels and military forces loyal to the Libyan leader Muammar Gaddafi.', 2011, 3, 17, 2011, 3, 26, 'day', '17 March 2011 – 26 March 2011', 43, 'https://en.wikipedia.org/wiki/Battle_of_Ajdabiya'),
  ('Q581087', 'Third Battle of Brega', 'The Third Battle of Brega was fought during the Libyan Civil War between government forces and anti-Gaddafi forces for control of the town of Brega and its surroundings.', 2011, 3, 31, 2011, 4, 7, 'day', '31 March 2011 – 7 April 2011', 45, 'https://en.wikipedia.org/wiki/Third_Battle_of_Brega'),
  ('Q588059', 'Battle of Bin Jawad', 'The Battle of Bin Jawad took place in early March 2011 during the Libyan Civil War between forces loyal to Libyan leader Muammar Gaddafi and anti-Gaddafi forces for control of the town of Bin Jawad.', 2011, 3, 6, 2011, 3, 11, 'day', '6 March 2011 – 11 March 2011', 47, 'https://en.wikipedia.org/wiki/Battle_of_Bin_Jawad'),
  ('Q609013', 'Battle of Tripoli', 'The Battle of Tripoli (Arabic: ﻣﻌﺮﻛﺔ ﻃﺮﺍﺑﻠﺲ ma''arakat Ṭarābulis), sometimes referred to as the Fall of Tripoli (Arabic: سقوط طرابلس suqūt Ṭarābulis), was a military confrontation in Tripoli, Libya, between loyalists of Muammar Gaddafi, the longtime leader of Libya, and the National Transitional Council, which was attempting to overthrow Gaddafi and take control of the capital. The battle began on 20 August 2011, six months after the First Libyan Civil War started, with an uprising within the city; rebel forces outside the city planned an offensive to link up with elements within Tripoli,…', 2011, 8, 20, 2011, 8, 28, 'day', '20 August 2011 – 28 August 2011', 58, 'https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2011)'),
  ('Q775224', 'Battle of Bani Walid', 'The Battle of Bani Walid was a military operation in the Libyan Civil War conducted by anti-Gaddafi forces in September and October 2011, in an effort to take control of the desert city of Bani Walid from pro-Gaddafi forces. It began following days of force buildup on the part of the attackers, as well as skirmishes around the city.', 2011, 9, 30, 2011, 10, 17, 'day', '30 September 2011 – 17 October 2011', 43, 'https://en.wikipedia.org/wiki/Battle_of_Bani_Walid'),
  ('Q846532', 'First Gulf of Sidra offensive', 'The First Gulf of Sidra offensive was the second major rebel offensive of the Libyan Civil War. It was mounted by anti-Gaddafi forces immediately after their victory in the Battle of Ajdabiya.', 2011, 3, 26, 2011, 3, 30, 'day', '26 March 2011 – 30 March 2011', 43, 'https://en.wikipedia.org/wiki/First_Gulf_of_Sidra_offensive'),
  ('Q911471', 'Second Battle of Brega', 'The Second Battle of Brega took place during the Libyan Civil War. Eleven days earlier, anti-Gaddafi forces had beaten back an attempt by loyalist forces to take the town on 2 March 2011, in the First Battle of Brega.', 2011, 3, 15, 2011, 3, 15, 'day', '15 March 2011', 45, 'https://en.wikipedia.org/wiki/Second_Battle_of_Brega'),
  ('Q942901', 'Second Battle of Benghazi', 'The Second Battle of Benghazi was fought between army units and militiamen loyal to Libyan leader Muammar Gaddafi, and anti-Gaddafi forces in Benghazi on 19-20 March 2011 during the Libyan Civil War. The battle marked the start of a United Nations-mandated military intervention in the conflict, with fighter jets from the French Air Force attacking and destroying several pro-Gaddafi units, forcing them to retreat.', 2011, 3, 19, 2011, 3, 20, 'day', '19 March 2011 – 20 March 2011', 47, 'https://en.wikipedia.org/wiki/Second_Battle_of_Benghazi'),
  ('Q989081', 'First Battle of Brega', 'The First Battle of Brega was fought during the Libyan Civil War. It began when pro-Gaddafi government troops attacked the city, held by the National Transitional Council, in the early hours of 2 March 2011.', 2011, 3, 2, NULL, NULL, NULL, 'day', '2 March 2011', 53, 'https://en.wikipedia.org/wiki/First_Battle_of_Brega'),
  ('Q1089511', 'Battle of Ra''s Lanuf', 'The Battle of Ras Lanuf was a two-phase battle in early to mid-March 2011 during the Libyan Civil War between forces loyal to Libyan leader Muammar Gaddafi and those loyal to the National Transitional Council. Both forces sought control of the town of Ras Lanuf.', 2011, 3, 4, 2011, 3, 5, 'day', '4 March 2011 – 5 March 2011', 48, 'https://en.wikipedia.org/wiki/Battle_of_Ras_Lanuf'),
  ('Q2270347', 'Battle of Misrata', 'The Battle of Misrata (Arabic: معركة مصراتة), also known as the Siege of Misrata, was a battle of the First Libyan Civil War for the control of Misrata. It was fought between troops loyal to the government of Muammar Gaddafi, and anti-Gaddafi rebels who held Misrata, the third largest city in Libya.', 2011, 2, 23, 2011, 5, 15, 'day', '23 February 2011 – 15 May 2011', 51, 'https://en.wikipedia.org/wiki/Battle_of_Misrata_(2011)'),
  ('Q2361214', 'Battle of Sirte', 'The Battle of Sirte was the final and most decisive battle of the First Libyan Civil War, beginning when the National Liberation Army attacked the last remnants of the Libyan army still loyal to Muammar Gaddafi in his hometown and designated capital of Sirte, on the Gulf of Sidra. As of September 2011, Sirte and Bani Walid were the last strongholds of Gaddafi loyalists and the National Transitional Council hoped that the fall of Sirte would bring the war to an end.', 2011, 9, 15, 2011, 10, 20, 'day', '15 September 2011 – 20 October 2011', 48, 'https://en.wikipedia.org/wiki/Battle_of_Sirte_(2011)'),
  ('Q2632974', 'Fourth Battle of Brega', 'The Fourth Battle of Brega was a battle in July and August 2011, during the Libyan Civil War, between forces loyal to Muammar Gaddafi and forces of the Libyan opposition for control of the strategic town of Brega and its oil port.', 2011, 7, 14, 2011, 7, 21, 'day', '14 July 2011 – 21 July 2011', 41, 'https://en.wikipedia.org/wiki/Fourth_Battle_of_Brega'),
  ('Q2888624', 'Battle of Gharyan', 'The Battle of Gharyan took place during the Libyan Civil War between rebel anti-Gaddafi forces and forces loyal to Muammar Gaddafi for control of the Tripolitanian city of Gharyan located at the eastern edge of the Nafusa Mountains.', 2011, 8, 13, 2011, 8, 18, 'day', '13 August 2011 – 18 August 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Gharyan_(2011)'),
  ('Q3477179', 'Battle of Wazzin', 'The Battle of Wazzin refers to a series of engagements during the First Libyan Civil War fought between Anti-Gaddafi forces and the Libyan Arab Jamahiriya for control of the town of Wazzin near the western Libya-Tunisia border. The battle entered into Tunisian territory on several occasions, prompting clashes between the Tunisian Armed Forces and Gaddafi Loyalists.', 2011, 4, 21, 2011, 7, 29, 'day', '21 April 2011 – 29 July 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Wazzin'),
  ('Q3545009', 'Second Battle of Zawiya', 'The Second Battle of Zawiya or Zawia took place during the Libyan Civil War between rebel anti-Gaddafi forces and forces loyal to Muammar Gaddafi for control of the Tripolitania city of Zawia.', 2011, 8, 13, 2011, 8, 20, 'day', '13 August 2011 – 20 August 2011', 39, 'https://en.wikipedia.org/wiki/Second_Battle_of_Zawiya'),
  ('Q4087321', 'Battle of Sabha', 'The Battle of Sabha was a part of the Libyan Civil War and took place between forces loyal to Libyan leader Muammar Gaddafi and rebel anti-Gaddafi forces for the control of the desert oasis city of Sabha. It was the second conflict in the city since the start of the war after the 2011 Sabha clashes.', 2011, 9, 19, 2011, 9, 22, 'day', '19 September 2011 – 22 September 2011', 37, 'https://en.wikipedia.org/wiki/Battle_of_Sabha'),
  ('Q4115092', 'Battle of Bayda', 'The Battle of Bayda was the first conflict that broke out during the First Libyan Civil War between the brigades of Colonel Muammar Gaddafi and the Libyan rebels in the 4th-largest city in the country, the city of Bayda and its suburbs. The battle took place as a result of the demonstrations calling for the fall of the regime in Bayda, and after that the demonstrators clashed with the personnel of the internal security agency in the city and the Talaa Khamis Brigade and the mercenaries and the Hussein Al-Jouifi Brigade stationed in Shahhat and Al Abraq International Airport in Bayda.', 2011, 2, 16, 2011, 2, 17, 'day', '16 February 2011 – 17 February 2011', 39, 'https://en.wikipedia.org/wiki/Battle_of_Bayda'),
  ('Q4124982', '2011–present Libyan factional fighting', 'Following the end of the First Libyan Civil War, which overthrew Muammar Gaddafi, there was violence involving various militias and the new state security forces. This violence escalated into the Second Libyan Civil War (2014–2020).', 2011, 11, 1, 2014, 5, 16, 'day', '1 November 2011 – 16 May 2014', 48, 'https://en.wikipedia.org/wiki/Factional_violence_in_Libya_(2011%E2%80%932014)'),
  ('Q4127865', 'Second Battle of Bin Jawad', 'The Second Battle of Bin Jawad took place during the Libyan Civil War between forces loyal to former Libyan leader Muammar Gaddafi and those loyal to the National Transitional Council for control of the small town of Bin Jawad.', 2011, 8, 23, 2011, 8, 27, 'day', '23 August 2011 – 27 August 2011', 39, 'https://en.wikipedia.org/wiki/Second_Battle_of_Bin_Jawad'),
  ('Q18702324', 'Libyan crisis', 'The Libyan crisis is the current humanitarian crisis and political-military instability occurring in Libya, beginning with the Arab Spring protests of 2011, which led to two civil wars, foreign military intervention, and the ousting and killing of Muammar Gaddafi. The first civil war''s aftermath and proliferation of armed groups led to violence and instability across the country, which erupted into renewed civil war in 2014.', 2011, 2, 15, NULL, NULL, NULL, 'day', '15 February 2011', 53, 'https://en.wikipedia.org/wiki/Libyan_crisis'),
  ('Q199416', '2012 Benghazi attack', 'Members of the Islamic militant group Ansar al-Sharia carried out a coordinated attack against two United States government facilities in Benghazi, Libya, on September 11, 2012. At 9:40 p.m.', 2012, 9, 11, NULL, NULL, NULL, 'day', '11 September 2012', 60, 'https://en.wikipedia.org/wiki/2012_Benghazi_attack'),
  ('Q4442941', '2012 Bani Walid uprising', 'The 2012 Bani Walid uprising was an event which started on 23 January 2012 due to an incident in the city of Bani Walid in which the "May 28 Brigade" militia wished to arrest local men in unclear circumstances. The May 28 Brigade and their compound were then attacked by local fighters who then took control of the town.', 2012, NULL, NULL, NULL, NULL, NULL, 'year', '2012', 37, 'https://en.wikipedia.org/wiki/2012_Bani_Walid_uprising'),
  ('Q16911838', 'Libyan Civil War', 'The Libyan civil war (2014–2020), also known as the Second Libyan Civil War, was a multilateral civil war which was fought in Libya among a number of armed groups, but mainly the House of Representatives (HoR) and the Government of National Accord (GNA), for six years from 2014 to 2020. The General National Congress (GNC), based in western Libya and backed by various militias with some support from Qatar and Turkey, initially accepted the results of the 2014 election, but rejected them after the Supreme Constitutional Court nullified an amendment regarding the roadmap for Libya''s transition…', 2014, 5, 16, 2020, 10, 23, 'day', '16 May 2014 – 23 October 2020', 70, 'https://en.wikipedia.org/wiki/Libyan_civil_war_(2014%E2%80%932020)'),
  ('Q19283494', '2015 kidnapping and beheading of Copts in Libya', 'The 21 Coptic Christian Martyrs of Libya are Christian construction workers who were killed for their Christian faith by the Islamic State (IS), and subsequently canonized as martyrs and saints by Pope Tawadros II. On 12 February 2015, the Islamic State released a video online showing photos of 21 Christian construction workers—twenty from Egypt and one from Ghana—that they had kidnapped in the city of Sirte, Libya, and who they reported had been killed for their faith in Jesus Christ. The men, who came from different villages in Egypt, 13 of them from Al-Our, Minya Governorate, were…', 2015, 2, 15, NULL, NULL, NULL, 'day', '15 February 2015', 58, 'https://en.wikipedia.org/wiki/21_Coptic_Christian_Martyrs_of_Libya'),
  ('Q19689146', 'Battle of Sirte (2015)', 'The Battle of Sirte refers to the battle in the spring of 2015, in the region of Sirte, Libya, between the Islamic State of Iraq and the Levant (ISIL) and the Libya Shield Force. ISIL forces had been present in the city since February 2015, before the Fall of Nofaliya.', 2015, 5, 31, NULL, NULL, NULL, 'day', '31 May 2015', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sirte_(2015)'),
  ('Q24467647', '2016 Sirte offensive', 'The Battle of Sirte during the Second Libyan Civil War started in the spring of 2016, in the Sirte District of Libya, between the Islamic State of Iraq and the Levant (ISIL) and the loyalist forces of the Government of National Accord (GNA) backed by the United States. ISIL forces had captured Sirte one year earlier, during the previous battle.', 2016, 12, 6, NULL, NULL, NULL, 'day', '6 December 2016', 39, 'https://en.wikipedia.org/wiki/Battle_of_Sirte_(2016)'),
  ('Q18544634', 'Fourth Battle of Benghazi', 'The Battle of Benghazi (2014–2017) was a major battle of the Second Libyan Civil War that raged from October 2014 to December 2017, between the Shura Council of Benghazi Revolutionaries, Islamic State of Iraq and the Levant in Libya, and the Libyan National Army (LNA), and paramilitaries supporting the LNA in the city. The battle was a direct consequence of the failed Benina Airport Offensive by the Benghazi Revolutionaries and their allies, which allowed LNA forces to regroup and attack deep into Benghazi.', 2017, 12, 30, NULL, NULL, NULL, 'day', '30 December 2017', 37, 'https://en.wikipedia.org/wiki/Battle_of_Benghazi_(2014%E2%80%932017)'),
  ('Q56682415', '2018 Tripoli Clashes', 'The Battle of Tripoli was a series of clashes in Tripoli, Libya from 27 August to 25 September 2018 during the Second Libyan Civil War. It was fought between several militias and was ended by a ceasefire.', 2018, 8, 27, 2018, 9, 25, 'day', '27 August 2018 – 25 September 2018', 37, 'https://en.wikipedia.org/wiki/Battle_of_Tripoli_(2018)'),
  ('Q53865794', 'Battle of Derna', 'The Battle of Derna was a military campaign by the Libyan National Army to recapture the city of Derna from the Shura Council of Mujahideen in Derna, which lasted from 7 May 2018 until 12 February 2019. The majority of military operations concluded by 28 June 2018, with the Libyan National Army declaring control of the entire city on that day, despite continued clashes in the old city.', 2019, 2, 12, NULL, NULL, NULL, 'day', '12 February 2019', 37, 'https://en.wikipedia.org/wiki/Battle_of_Derna_(2018%E2%80%932019)'),
  ('Q122311648', 'Storm Daniel', 'Storm Daniel, also known as Medicane Daniel or Cyclone Daniel, was a relatively weak yet catastrophic and erratic tropical cyclone that became the deadliest Mediterranean tropical-like cyclone in recorded history, as well as the second-costliest tropical cyclone on record outside of the North Atlantic Basin (after Typhoon Doksuri). Forming as a low-pressure system around 4 September 2023, the storm affected Greece, Bulgaria, and Turkey with extensive flooding.', 2023, 9, NULL, 2023, 9, 13, 'month', 'September 2023 – 13 September 2023', 72, 'https://en.wikipedia.org/wiki/Storm_Daniel'),
  ('Q134455210', '2025 Tripoli clashes', 'On 12 May 2025, clashes broke out in Tripoli, Libya, between the 444th Infantry Brigade and the Stability Support Apparatus (SSA). The fighting began after SSA commander Abdel Ghani al-Kikli was assassinated.', 2025, 5, 12, NULL, NULL, NULL, 'day', '12 May 2025', 37, 'https://en.wikipedia.org/wiki/2025_Tripoli_clashes');
